#!/usr/bin/env python3

from autopep8 import fix_code

INDENTED_DOC = """def foo():
    print('asdf',
    file=None
    )

bar = { 'foo': foo
}
"""

# Test with various aggressive settings
for agg in [0, 1, 2]:
    print(f"Testing with aggressive={agg}")
    try:
        result = fix_code(INDENTED_DOC, options={'aggressive': agg})
        print(f"  Success: {repr(result[:50])}...")
    except Exception as e:
        print(f"  Error: {e}")

# Test with defaults
print("Testing with defaults")
try:
    result = fix_code(INDENTED_DOC, options={})
    print(f"  Success: {repr(result[:50])}...")
except Exception as e:
    print(f"  Error: {e}")

