from autopep8 import fix_code

INDENTED_DOC = """def foo():
    print('asdf',
    file=None
    )

bar = { 'foo': foo
}
"""

# Try different aggressive values
for agg in [-1, 0, 1, 2, 3, 4, 5]:
    try:
        result = fix_code(INDENTED_DOC, options={'aggressive': agg})
        print(f"aggressive={agg}: SUCCESS")
    except Exception as e:
        print(f"aggressive={agg}: ERROR - {e}")

# Try other combinations
combos = [
    {},
    {'max_line_length': 79},
    {'max_line_length': 79, 'aggressive': 0},
    {'select': []},
    {'ignore': []},
    {'max_line_length': 79, 'select': [], 'ignore': []},
]

for i, opts in enumerate(combos):
    try:
        result = fix_code(INDENTED_DOC, options=opts)
        print(f"combo {i} {opts}: SUCCESS")
    except Exception as e:
        print(f"combo {i} {opts}: ERROR - {e}")

